 if(action==='editApplyStyle'){const members=groupMembers(f),vals={styleColor:$('#editStyleColor')?.value||f.properties.styleColor,styleWeight:+$('#editStyleWeight')?.value||f.properties.styleWeight||2,styleDash:$('#editStyleDash')?.value||'solid',styleFill:$('#editStyleFill')?.value||f.properties.styleFill};for(const x of members.filter(x=>!x.properties.guideHidden)){Object.assign(x.properties,vals);if($('#editShowArrow'))x.properties.showArrow=$('#editShowArrow').checked;}commit();renderDrawer('selection');toast('Style updated'+(members.length>1?' across the group':'')+'.');return;}
 if(action==='editRotate'){const a=(+$('#editAngle').value||0)*Math.PI/180,b=G.boundsOf(f.geometry),center=[(b[0]+b[2])/2,(b[1]+b[3])/2],p=G.projection(center);transformGeometry(f.geometry,c=>{const[x,y]=p.xy(c);return p.ll([x*Math.cos(a)+y*Math.sin(a),-x*Math.sin(a)+y*Math.cos(a)]);});commit();toast('Rotation applied.');}
