function editMarker(p){return L.marker(latlng(p),{draggable:true,icon:L.divIcon({className:'',html:'<div class="vertex-handle"></div>',iconSize:[17,17],iconAnchor:[8,8]})}).addTo(state.editGroup);}
function transformGeometry(g,fn){function walk(a){if(typeof a[0]==='number')return fn(a);return a.map(walk);}g.coordinates=walk(g.coordinates);}
async function findPlace(){const q=$('#placeQuery')?.value.trim(),out=$('#placeResults');if(!q||!out)return;out.innerHTML='<p class="subtle">Searching…</p>';try{const coordLike=/^-?\d+(?:\.\d+)?\s*,\s*-?\d+(?:\.\d+)?$/.test(q),w3w=W3W_RE.test(q);if(coordLike||w3w){const x=await resolveLocationText(q);if(!out.isConnected)return;out.innerHTML='<button class="wide-btn primary" data-resolved="1">'+esc(x.label)+'</button>';out.querySelector('[data-resolved]').onclick=()=>goTo(x.coord);return;}const r=await window.SAMINetwork.geocode('https://nominatim.openstreetmap.org/search?format=json&limit=6&q='+encodeURIComponent(q),{signal:AbortSignal.timeout(10000),headers:{Accept:'application/json'}});if(!r.ok)throw Error('Search source unavailable');const data=await r.json();if(!out.isConnected)return;out.innerHTML=data.length?data.map((x,i)=>'<button class="wide-btn" data-place="'+i+'">'+esc(x.display_name)+'</button>').join(''):'<p class="subtle">No matches found.</p>';out.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{const x=data[+b.dataset.place];goTo([+x.lon,+x.lat]);});}catch(e){if(out.isConnected)out.innerHTML='<p class="subtle">'+esc(e.message||'Search is unavailable. Use coordinates or current location.')+'</p>';}}
function goCoords(){const p=[Number($('#lngInput').value),Number($('#latInput').value)];if(!$('#latInput').value||!$('#lngInput').value||!G.validCoord(p)){toast('Enter valid latitude and longitude.');return;}goTo(p);}
function goTo(c){closeDrawer();dismissWelcome();state.map.setView(latlng(c),18);}
function locate(){if(!navigator.geolocation){toast('Location is unavailable.');return;}toast('Finding your location…');navigator.geolocation.getCurrentPosition(p=>{const c=[p.coords.longitude,p.coords.latitude];goTo(c);const m=L.circleMarker(latlng(c),{color:'#fff',weight:3,radius:7,fillColor:'#0875f5',fillOpacity:1}).addTo(state.map);setTimeout(()=>state.map.removeLayer(m),12000);},()=>toast('Location could not be read. Allow permission or enter coordinates.'),{enableHighAccuracy:true,timeout:10000});}
async function handlePhoto(ev){const f=ev.target.files?.[0];ev.target.value='';if(!f)return;if(!f.type.startsWith('image/')){toast('Choose an image file.');return;}try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);});const im=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=data;});const scale=Math.min(1,1200/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=im.width*scale;c.height=im.height*scale;c.getContext('2d').drawImage(im,0,0,c.width,c.height);startTool('photo',{label:f.name,name:f.name,data:c.toDataURL('image/jpeg',.76),includeOnDrawing:state.mode!=='map',includeLegend:state.mode!=='map'});}catch{toast('This image could not be opened. Try a JPEG or PNG.');}}
function sourceFeatures(data){if(data?.crs&&!/4326|CRS84/i.test(JSON.stringify(data.crs)))throw Error('Export the source as WGS84 GeoJSON (EPSG:4326 / CRS84).');const fs=data?.type==='FeatureCollection'?data.features:data?.type==='Feature'?[data]:null;if(!Array.isArray(fs))throw Error('Choose a GeoJSON FeatureCollection or Feature.');if(fs.length>10000)throw Error('The file exceeds 10,000 records. Export a smaller site area.');return fs;}
function prepareServices(data,source,fallback,selectedOnly=true){const results=[],skipped={outside:0,invalid:0,hidden:0},clip=serviceBounds();for(const f of sourceFeatures(data)){if(!G.validateFeature(f)){skipped.invalid++;continue;}const m=cleanMeta(f.properties),type=SERVICES[m.serviceType]?m.serviceType:SERVICES[m.service_type]?m.service_type:fallback;if(selectedOnly&&state.project.serviceVisibility[type]===false){skipped.hidden++;continue;}let geometry;try{geometry=G.clipGeometry(f.geometry,clip);}catch{skipped.invalid++;continue;}if(!geometry){skipped.outside++;continue;}results.push(feature('service',geometry,{...m,type:'service',serviceType:type,label:m.label||m.name||SERVICES[type]?.name||'Service / constraint',source:m.source||source,sourceId:source,verification:m.verification||'Source record · verify on site',provenance:m.provenance||'Imported project / data-pack record',imported:new Date().toISOString(),includeLegend:true}));}return{results,skipped};}
async function handleImport(ev){const file=ev.target.files?.[0];ev.target.value='';if(!file)return;try{if(file.size>50*1024*1024)throw Error('Choose a file smaller than 50 MB.');let data;try{data=JSON.parse(await file.text());}catch{throw Error('This file could not be read. Choose a valid SAMI backup or GeoJSON file.');}if(state.importKind==='project'){const p=normaliseProject(data);showModal('Restore this project?','<p>Import <strong>'+esc(p.name)+'</strong> with '+p.features.length+' items. A separate project copy will open; your current project is kept.</p>'+button('Import project copy','confirmRestore',true));$('#modalBody').onclick=async e=>{const button=e.target.closest('[data-action="confirmRestore"]');if(!button)return;button.disabled=true;try{if(!await window.SAMIWorkspace.save(true,'Before importing backup'))return;p.id=crypto.randomUUID?.()||'import-'+Date.now();p.createdAt=new Date().toISOString();await window.SAMIWorkspace.loadProject(p);closeModal();toast('Backup imported as a separate project. Your previous project is kept.');}catch(error){toast('Import: '+error.message);}finally{button.disabled=false;}};return;}
 if(!state.project.area)throw Error('Define a site area before importing services.');const k=state.importServiceType||state.project.serviceType;state.project.serviceVisibility[k]=true;state.project.hiddenTypes=state.project.hiddenTypes.filter(t=>t!=='service');const {results,skipped}=prepareServices(data,file.name,k,false);if(state.project.features.length+results.length>12000)throw Error('This project exceeds 12,000 items. Split the project.');const sourceId='file:'+file.name;results.forEach(f=>{f.properties.sourceId=sourceId;});await archiveActiveSource(sourceId,'Previous import · '+file.name);state.project.features=state.project.features.filter(f=>f.properties.sourceId!==sourceId);state.project.features.push(...results);commit();state.lastLoad=results.length+' records imported into site + 0.25 mile service buffer. '+skipped.outside+' outside, '+skipped.hidden+' hidden types, '+skipped.invalid+' unsupported / invalid.';openDrawer('services');toast(state.lastLoad);
 }catch(e){toast('Import: '+e.message);}}
function abortLayerRequest(){state.request?.abort();state.request=null;}
async function boundedJSON(response,max=4*1024*1024){if(!response.ok)throw Error('Source returned HTTP '+response.status);if(+response.headers.get('content-length')>max)throw Error('Source response is too large. Query a smaller site area.');if(!response.body){const t=await response.text();if(t.length>max)throw Error('Source response is too large.');return JSON.parse(t);}const reader=response.body.getReader(),parts=[];let size=0;try{while(true){const {done,value}=await reader.read();if(done)break;size+=value.byteLength;if(size>max){await reader.cancel();throw Error('Source response is too large.');}parts.push(value);}}finally{reader.releaseLock();}const bytes=new Uint8Array(size);let offset=0;parts.forEach(p=>{bytes.set(p,offset);offset+=p.length;});return JSON.parse(new TextDecoder().decode(bytes));}
async function loadServices(){
 const area=state.project.area,selected=Object.keys(SERVICES).filter(k=>state.project.serviceVisibility[k]);if(!area){openDrawer('area');return;}if(!selected.length){toast('Select at least one service or constraint type.');return;}
 const sources=(window.SAMI_CONFIG?.serviceSources||[]).filter(s=>s.enabled!==false&&s.url&&selected.includes(s.type));if(!sources.length){state.lastLoad='No authorised connector is configured for these selected types. Use the overhead-line snapshot, an approved data pack, or project survey records.';renderDrawer('services');toast(state.lastLoad);return;}
 abortLayerRequest();const controller=new AbortController();state.request=controller;const generation=state.areaGeneration,b=serviceBounds(),bbox=b.join(','),captured=JSON.stringify(selected);state.lastLoad='Loading records only inside the site + 0.25 mile buffer…';renderDrawer('services');const pending=[],errors=[];const timer=setTimeout(()=>controller.abort(),25000);
 try{for(const src of sources){if(controller.signal.aborted)break;try{const sourceId='source:'+src.url+':'+src.type,key=sourceId+'|'+bbox,hit=state.cache.get(key);let data;if(hit&&Date.now()-hit.time<300000)data=hit.data;else{const url=new URL(src.url,location.href);if(url.protocol!=='https:'&&url.origin!==location.origin)throw Error('Use an HTTPS data source.');url.searchParams.set('bbox',bbox);url.searchParams.set('crs','EPSG:4326');url.searchParams.set('limit','10000');data=await boundedJSON(await fetch(url.href,{signal:controller.signal,headers:{Accept:'application/geo+json,application/json'}}));state.cache.set(key,{data,time:Date.now()});if(state.cache.size>10)state.cache.delete(state.cache.keys().next().value);}if(controller.signal.aborted)break;const res=prepareServices(data,src.name||src.url,src.type);res.results.forEach(f=>{f.properties.sourceId=sourceId;f.properties.source=src.name||src.url;});pending.push({sourceId,label:src.name||src.type,features:res.results});}catch(e){if(e.name!=='AbortError')errors.push((src.name||src.type)+': '+e.message);}}
 if(controller.signal.aborted||generation!==state.areaGeneration||bbox!==serviceBounds()?.join(',')||captured!==JSON.stringify(Object.keys(SERVICES).filter(k=>state.project.serviceVisibility[k]))){state.lastLoad='Load stopped. Run refresh for the current site area.';return;}
 let next=state.project.features;for(const batch of pending){await archiveActiveSource(batch.sourceId,'Previous snapshot · '+batch.label);next=next.filter(f=>f.properties.sourceId!==batch.sourceId).concat(batch.features);}if(next.length>12000)throw Error('Too many records for this project. Use a smaller site area.');state.project.features=next;state.project.hiddenTypes=state.project.hiddenTypes.filter(t=>t!=='service');commit();state.lastLoad=pending.reduce((n,b)=>n+b.features.length,0)+' records refreshed in site + 0.25 mile buffer; previous source snapshots archived.'+(errors.length?' '+errors.join(' '):'');
 }catch(e){state.lastLoad=e.message;}finally{clearTimeout(timer);if(state.request===controller)state.request=null;if(state.drawer==='services')renderDrawer('services');toast(state.lastLoad);}
}
function formatDistance(n){return n>=1000?(n/1000).toFixed(2)+' km':n.toFixed(n<100?1:0)+' m';}
function safeName(){return state.project.name.replace(/[^a-z0-9_-]+/gi,'_')||'SAMI_Project';}
function download(name,text,type){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
function projectGeoJSON(){const features=copy(state.project.features);if(state.project.area)features.unshift(feature('plan-area',G.boundsGeometry(state.project.area),{label:'Defined site area',includeLegend:false}));features.forEach(f=>{delete f.properties.data;});return{type:'FeatureCollection',name:state.project.name,features};}
function exportProjectJSON(){window.SAMIWorkspace?.checkpointDraft?.();download(safeName()+'.sami',JSON.stringify(state.project,null,2),'application/json');window.SAMIField?.backupRequested?.(state.project.id);}
function exportGeoJSON(){download(safeName()+'_SAMI.geojson',JSON.stringify(projectGeoJSON(),null,2),'application/geo+json');}
function exportCSV(){const rows=[['Item','Type','Length (m)','Width (m)','Quantity','Source / reference']],groups=new Map();for(const f of state.project.features){const m=f.properties;if(['panel','asset'].includes(m.type)){const k=[m.label,m.type,m.length,m.width].join('|');if(!groups.has(k))groups.set(k,[m.label,m.type,m.length||'',m.width||'',0,'']);groups.get(k)[4]++;}else rows.push([m.label,TYPES[m.type]||m.type,m.type==='measure'?geometryLength(f.geometry).toFixed(2):'','',1,m.source||'']);}rows.push(...groups.values());const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"';download(safeName()+'_materials.csv','\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function exportKML(){function geom(g){const coords=ps=>ps.map(c=>c[0]+','+c[1]+',0').join(' ');if(g.type==='Point')return'<Point><coordinates>'+coords([g.coordinates])+'</coordinates></Point>';if(g.type==='LineString')return'<LineString><coordinates>'+coords(g.coordinates)+'</coordinates></LineString>';if(g.type==='Polygon')return'<Polygon>'+g.coordinates.map((r,i)=>'<'+(i?'inner':'outer')+'BoundaryIs><LinearRing><coordinates>'+coords(r)+'</coordinates></LinearRing></'+(i?'inner':'outer')+'BoundaryIs>').join('')+'</Polygon>';const map={MultiPoint:'Point',MultiLineString:'LineString',MultiPolygon:'Polygon'};return'<MultiGeometry>'+g.coordinates.map(c=>geom({type:map[g.type],coordinates:c})).join('')+'</MultiGeometry>';}
 const out='<?xml version="1.0" encoding="UTF-8"?><kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>'+esc(state.project.name)+'</name>'+projectGeoJSON().features.map(f=>'<Placemark><name>'+esc(f.properties.label)+'</name>'+geom(f.geometry)+'</Placemark>').join('')+'</Document></kml>';download(safeName()+'_SAMI.kml',out,'application/vnd.google-earth.kml+xml');}
function exportDXF(){const features=projectGeoJSON().features.concat(copy(state.project.planBase||[]).map(f=>({...f,properties:{...f.properties,type:'planBase'}}))),origin=planBounds()?.slice(0,2)||state.project.area?.slice(0,2)||coord(state.map.getCenter()),pr=G.projection(origin);let out='999\nSAMI true-scale local metre export; origin longitude '+origin[0]+' latitude '+origin[1]+'\n0\nSECTION\n2\nHEADER\n9\n$INSUNITS\n70\n6\n0\nENDSEC\n0\nSECTION\n2\nENTITIES\n';function geom(g,layer){if(g.type==='Point'){const[x,y]=pr.xy(g.coordinates);out+='0\nPOINT\n8\n'+layer+'\n10\n'+x.toFixed(3)+'\n20\n'+y.toFixed(3)+'\n30\n0\n';}else if(g.type==='LineString'){out+='0\nLWPOLYLINE\n8\n'+layer+'\n90\n'+g.coordinates.length+'\n70\n0\n';g.coordinates.forEach(c=>{const[x,y]=pr.xy(c);out+='10\n'+x.toFixed(3)+'\n20\n'+y.toFixed(3)+'\n';});}else if(g.type==='Polygon')g.coordinates.forEach((r,i)=>{out+='0\nLWPOLYLINE\n8\n'+layer+'\n90\n'+r.length+'\n70\n1\n';r.forEach(c=>{const[x,y]=pr.xy(c);out+='10\n'+x.toFixed(3)+'\n20\n'+y.toFixed(3)+'\n';});});else{const map={MultiPoint:'Point',MultiLineString:'LineString',MultiPolygon:'Polygon'};g.coordinates.forEach(c=>geom({type:map[g.type],coordinates:c},layer));}}
 for(const f of features){let g=f.geometry;if(state.project.area){try{g=G.clipGeometry(g,planBounds());}catch{}}if(!g)continue;const layer=((f.properties.baseClass?'BASE_'+f.properties.baseClass:(f.properties.serviceType||f.properties.type||'SAMI'))).replace(/[^a-z0-9_-]/gi,'_').toUpperCase();geom(g,layer);}out+='0\nENDSEC\n0\nEOF\n';download(safeName()+'_SAMI_true_scale.dxf',out,'application/dxf');}
