function readDocumentOptions(){const layers={};$$('[data-doc-layer]').forEach(el=>layers[el.dataset.docLayer]=el.checked);const opt={pages:{site:$('#docPageSite')?.checked!==false,route:$('#docPageRoute')?.checked!==false},style:$('input[name="docStyle"]:checked')?.value||'cad',paper:$('input[name="docPaper"]:checked')?.value||'a3',layers,revision:$('#docRevision')?.value.trim()||'',status:$('#docStatus')?.value||'',preparedBy:$('#docPrepared')?.value.trim()||'',notes:$('#docNotes')?.value.trim()||''};if(!opt.pages.site&&!opt.pages.route)throw Error('Select at least one page.');return opt;}
