let modalFocus;function modalTrap(e){if(e.key!=='Tab')return;const card=$('#modal .modal-card');if(!card)return;const items=[...card.querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')].filter(el=>!el.disabled&&el.offsetParent!==null);if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}function showModal(title,html){modalFocus=document.activeElement;$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modalBody').onclick=null;const modal=$('#modal'),footer=$('#modalFooter');if(footer){footer.hidden=true;footer.innerHTML='';footer.onclick=null;}modal.classList.toggle('about-modal',title==='SAMI');modal.classList.toggle('export-modal',title.startsWith('EXPORT / ISSUE'));modal.classList.remove('hidden');document.body.classList.add('modal-open');$('#modalBody').scrollTop=0;$('#modalClose').focus();document.addEventListener('keydown',modalTrap);}function closeModal(){const modal=$('#modal'),footer=$('#modalFooter');modal.classList.add('hidden');modal.classList.remove('export-modal');document.body.classList.remove('modal-open');if(footer){footer.hidden=true;footer.innerHTML='';footer.onclick=null;}document.removeEventListener('keydown',modalTrap);modalFocus?.focus?.();}
function updateRailButton(){const c=$('#toolRail').classList.contains('collapsed');$('#railCollapse').textContent=c?'☰':'‹';$('#railCollapse').setAttribute('aria-expanded',String(!c));$('#railCollapse').setAttribute('aria-label',c?'Expand planning tools':'Collapse planning tools');}
function saveRail(){const r=$('#toolRail');setPref('sami.toolrail',JSON.stringify({left:parseFloat(r.style.left),top:parseFloat(r.style.top),collapsed:r.classList.contains('collapsed'),dock:r.dataset.dock||''}));}
function clampRail(){const r=$('#toolRail'),w=$('#workspace');if(r.dataset.dock){r.style.left='';r.style.top='';return;}if(!r.style.top)return;const rightReserve=68;const maxX=Math.max(7,w.clientWidth-r.offsetWidth-rightReserve),maxY=Math.max(55,w.clientHeight-r.offsetHeight-85);r.style.left=Math.max(7,Math.min(maxX,parseFloat(r.style.left)||7))+'px';r.style.top=Math.max(55,Math.min(maxY,parseFloat(r.style.top)||55))+'px';}
function initToolRail(){const r=$('#toolRail'),h=$('#railMove');let p={};try{p=JSON.parse(readPref('sami.toolrail')||'{}');}catch{}if(p.collapsed)r.classList.add('collapsed');if(p.dock){r.dataset.dock=p.dock;r.classList.add('dock-horizontal','dock-'+p.dock);}else if(Number.isFinite(p.left)&&Number.isFinite(p.top)){r.style.left=p.left+'px';r.style.top=p.top+'px';clampRail();}updateRailButton();$('#railCollapse').onclick=()=>{r.classList.toggle('collapsed');updateRailButton();clampRail();saveRail();};let drag=null;h.onpointerdown=e=>{const b=r.getBoundingClientRect(),w=$('#workspace').getBoundingClientRect();if(r.dataset.dock){r.dataset.dock='';r.classList.remove('dock-horizontal','dock-top','dock-bottom');r.style.left=(b.left-w.left)+'px';r.style.top=(b.top-w.top)+'px';}drag={dx:e.clientX-b.left,dy:e.clientY-b.top};h.setPointerCapture(e.pointerId);e.preventDefault();};h.onpointermove=e=>{if(!drag)return;const b=$('#workspace').getBoundingClientRect();r.style.left=e.clientX-b.left-drag.dx+'px';r.style.top=e.clientY-b.top-drag.dy+'px';clampRail();};const stop=e=>{if(!drag)return;drag=null;h.releasePointerCapture?.(e.pointerId);const rb=r.getBoundingClientRect(),wb=$('#workspace').getBoundingClientRect(),snap=72;if(rb.top-wb.top<snap){r.dataset.dock='top';r.classList.add('dock-horizontal','dock-top');r.style.left='';r.style.top='';toast('Toolbar docked horizontally at the top.');}else if(wb.bottom-rb.bottom<snap+70){r.dataset.dock='bottom';r.classList.add('dock-horizontal','dock-bottom');r.style.left='';r.style.top='';toast('Toolbar docked horizontally at the bottom.');}saveRail();};h.onpointerup=stop;h.onpointercancel=stop;}
const W3W_RE=/^(?:\/\/\/)?([\p{L}\p{M}-]+)\.([\p{L}\p{M}-]+)\.([\p{L}\p{M}-]+)$/u;
