async function handleCommand(q){const n=q.toLowerCase().trim();
 if(/^(undo|undo that|go back one)[.!]?$/.test(n)){undo();samiSay('Undo requested.');return;}if(/^redo/.test(n)){redo();samiSay('Redo requested.');return;}
 if(/unlock.*(map|plan|view)/.test(n)){setLock(false);samiSay('View unlocked.');return;}if(/lock.*(map|plan|view)/.test(n)){setLock(true);samiSay('View locked. Drawing tools remain available.');return;}
 if(/satellite/.test(n)){switchBase('satellite');samiSay('Satellite background opened. Your site drawing remains editable.');return;}
 if(/site drawing|plan drawing|drawing view|open (the )?plan/.test(n)){setMode('plan');samiSay('Site Drawing is open. Draw over Map, Satellite or switch separately to the CAD background.');return;}
 if(/define|set|create/.test(n)&&/(?:plan|site) area/.test(n)){openDrawer('area');samiSay('Draw the site area freehand, choose two opposite corners, or use the visible map area.');return;}
 if(tryHandleIntelligentObject(q))return;
 if(/map view|street view/.test(n)){switchBase('street');samiSay('Map background opened.');return;}
 if(/open|show|add|build/.test(n)&&/panel|trakway/.test(n)){openDrawer('panels');samiSay('Trakway is an on-site plan asset. Choose the product and run width, then draw the Trakway run on the site plan.');return;}
 if(/route to site|hgv route|lorry route|truck route/.test(n)){setMode('route');samiSay('Route to site is open. Choose the vehicle profile and enter or pick the two route endpoints.');return;}
 if(/open|show|add/.test(n)&&/assets?|welfare|cabin/.test(n)){openDrawer('assets');samiSay('Choose a site asset, adjust its dimensions and place it.');return;}
 if(/open|show|load/.test(n)&&/services?|constraints?|utilities/.test(n)){openDrawer('services');samiSay('Choose the types to display. Service data is limited to the site plus the quarter-mile buffer and should be verified before safety-critical use.');return;}
 if(/library/.test(n)){setMode('library');samiSay('The materials and item library is open.');return;}
 if(/zoom in|zoom out/.test(n)){n.includes('in')?state.map.zoomIn():state.map.zoomOut();samiSay('Zoom changed.');return;}
 if(/my location|current location|where am i/.test(n)){locate();samiSay('Requesting your current location.');return;}if(/fit.*(site|plan|project)/.test(n)){fitProject();samiSay('Fit plan requested.');return;}
 if(/draw|start|create/.test(n)&&/stone road/.test(n)){startStoneRoad();samiSay('Set the stone-road width, then draw its centre line.');return;}if(/draw|start|create/.test(n)&&/excavat/.test(n)){startTool('excavation',{label:'Excavation',includeLegend:true});samiSay('Tap the excavation footprint, then press Finish.');return;}if(/add|create/.test(n)&&/text box|textbox/.test(n)){startTextBox();samiSay('Enter the drawing annotation, then choose its position.');return;}if(/draw|start|create/.test(n)&&/access|egress|measure|area|on[- ]?site route/.test(n)){const t=n.includes('access')?'access':n.includes('egress')?'egress':n.includes('measure')?'measure':n.includes('area')?'area':'route';startTool(t,{snap:t==='measure',includeLegend:t!=='measure'});samiSay('Tap your points, then press Finish.');return;}
 if(/add|create|place/.test(n)&&/note/.test(n)){const text=q.replace(/^.*?note\s*/i,'').trim();if(text)startTool('note',{text,label:text});else startNote();samiSay('Tap where you want the note placed.');return;}
 if(/export/.test(n)){if(/dxf|cad/.test(n))exportDXF();else if(/geojson/.test(n))exportGeoJSON();else if(/kml/.test(n))exportKML();else if(/csv|schedule/.test(n))exportCSV();else openExport();samiSay('Your export is ready to choose or download.');return;}
 const source=trustedSources.map(s=>({s,score:s.keys.filter(k=>n.includes(k)).length})).sort((a,b)=>b.score-a.score)[0];if(source?.score){addMessage('sami','Here is a relevant official reference. Open it to check the governing guidance and project requirements.',source.s);speakOptional('I have linked the official source on screen.');return;}
 if(window.SAMI_CONFIG?.aiEndpoint){await askConnectedAI(q);return;}samiSay('Try “create a 15 x 15 metre pad in Lion panels”, “add a concrete mixer truck”, “open panels”, “define site area”, “satellite view” or “undo”. Open Help on the side to find all planning tools.');}
async function askConnectedAI(query){try{const r=await fetch(window.SAMI_CONFIG.aiEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query,project:{name:state.project.name,area:state.project.area,itemCount:state.project.features.length,currentPanelProduct:state.project.route?.product},catalog:{panels:Object.fromEntries(Object.entries(PRODUCTS).map(([k,v])=>[k,{name:v.name,length:v.length,width:v.width,overlap:v.overlap,lateralOverlap:v.lateralOverlap}])),assetKinds:Object.keys(ASSETS)},policy:'official-source-grounded; never invent physical dimensions; researched asset actions require an HTTPS source and explicit dimensions',allowMapActions:true,allowObjectGeneration:true}),signal:AbortSignal.timeout(20000)});const data=await boundedJSON(r,200000);if(typeof data.answer!=='string')throw Error();samiSay(data.answer.slice(0,12000));for(const s of (Array.isArray(data.sources)?data.sources:[]).slice(0,8))addMessage('sami','Source',s);const a=data.action;if(a?.type==='activateTool'&&['access','egress','route','area','measure','hazard'].includes(a.tool))startTool(a.tool);else if(a?.type==='setView'&&G.validCoord([a.lng,a.lat])){if(state.mode==='plan')setMode('map');state.map.setView([a.lat,a.lng],Math.max(3,Math.min(23,Number(a.zoom)||18)));}else if(a?.type==='createPanelPad'){const pk=PRODUCTS[a.product]?a.product:(state.project.route?.product||'lion');createPanelPadObject({type:'panelPad',product:pk,widthM:+a.widthM,heightM:+a.heightM,fitMode:['closest','atLeast','inside'].includes(a.fitMode)?a.fitMode:'closest'});}else if(a?.type==='createCatalogAsset'&&ASSETS[a.kind])createCatalogAssetObject(a.kind,{generated:true});else if(a?.type==='createResearchedAsset')createExternallySpecifiedAssetObject(a);}catch{samiSay('The connected service did not respond. Local drawing and map commands still work.');}}
let deferredInstallPrompt=null;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;updateLaunchGate();});
window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;updateLaunchGate(true);});
function isStandaloneApp(){return window.matchMedia?.('(display-mode: standalone)').matches||window.navigator.standalone===true;}
function setupLaunchGate(){updateLaunchGate();}
function closeInstallFallback(){const el=$('#installFallback');if(el)el.classList.remove('open');}
function showInstallFallback(){const box=$('#installFallback'),text=$('#installFallbackText');if(!box||!text)return;const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1;text.innerHTML=ios?'Safari does not expose a one-tap install prompt. Tap <b>Share</b> then <b>Add to Home Screen</b>. This is an iOS browser limitation.':'Open your browser menu and choose <b>Install app</b> or <b>Add to Home Screen</b>.';box.classList.add('open');clearTimeout(showInstallFallback.t);showInstallFallback.t=setTimeout(closeInstallFallback,7000);}
function leaveLaunch(){const splash=$('#splash');if(!splash)return;splash.classList.add('launching');setTimeout(()=>splash.remove(),470);}
function updateLaunchGate(justInstalled=false){const splash=$('#splash');if(!splash)return;const start=$('#launchStartBtn'),install=$('#installPwaBtn'),guide=$('#installGuide'),status=$('#splashStatus'),fallbackClose=$('#installFallbackClose');const standalone=isStandaloneApp();start.hidden=!standalone;install.hidden=standalone;guide.hidden=true;document.documentElement.classList.toggle('browser-gated',!standalone);if(fallbackClose)fallbackClose.onclick=closeInstallFallback;if(standalone){status.textContent=justInstalled?'SAMI is installed and ready.':'Your site intelligence workspace is ready.';start.textContent='Open SAMI';start.onclick=leaveLaunch;}else{status.textContent=deferredInstallPrompt?'Install SAMI for the full-screen site-planning experience.':'Add SAMI to your Home Screen for the full-screen site-planning experience.';install.textContent='Add SAMI to Home Screen';install.onclick=async()=>{if(deferredInstallPrompt){const p=deferredInstallPrompt;deferredInstallPrompt=null;try{p.prompt();await p.userChoice;}catch{}updateLaunchGate();}else showInstallFallback();};}}
function isFreehandTool(t){return['panelFreehand','panelAreaFreehand','planAreaFreehand','serviceFreehand','accessFreehand','egressFreehand','routeFreehand','areaFreehand','hazardFreehand','excavationFreehand','arrowFreehand','stoneRoadFreehand','stoneAreaFreehand'].includes(t);}
function screenToCoord(e){const pt=state.map.mouseEventToContainerPoint?state.map.mouseEventToContainerPoint(e):L.point(e.clientX-$('#map').getBoundingClientRect().left,e.clientY-$('#map').getBoundingClientRect().top);return coord(state.map.containerPointToLatLng(pt));}
function freehandPointAllowed(c){if(state.tool==='serviceFreehand'&&state.project.area&&!G.inside(c,serviceBounds()))return false;if(state.mode==='plan'&&state.project.area&&!['planAreaFreehand','serviceFreehand'].includes(state.tool)&&!insidePlanFrame(c))return false;return true;}
function initFreehandInput(){const el=$('#map');let pointer=null,lastPx=null;el.addEventListener('pointerdown',e=>{if(!isFreehandTool(state.tool)||pointer!==null||e.button>0)return;const c=screenToCoord(e);if(!freehandPointAllowed(c)){toast('Start inside the active drawing area.');return;}pointer=e.pointerId;state.freehandActive=true;state.points=[c];lastPx={x:e.clientX,y:e.clientY};state.map.dragging.disable();el.setPointerCapture?.(e.pointerId);e.preventDefault();e.stopPropagation();renderDraft();},{capture:true});el.addEventListener('pointermove',e=>{if(pointer!==e.pointerId||!state.freehandActive)return;const d=Math.hypot(e.clientX-lastPx.x,e.clientY-lastPx.y);if(d<5)return;const c=screenToCoord(e);if(!freehandPointAllowed(c))return;const prev=state.points.at(-1);if(!prev||G.distance(prev,c)>.18){state.points.push(c);lastPx={x:e.clientX,y:e.clientY};renderDraft();}e.preventDefault();e.stopPropagation();},{capture:true});const finish=e=>{if(pointer!==e.pointerId)return;el.releasePointerCapture?.(e.pointerId);pointer=null;state.freehandActive=false;const t=state.tool;updateLock();const lines=['panelFreehand','accessFreehand','egressFreehand','routeFreehand','arrowFreehand','stoneRoadFreehand'];const min=(t==='serviceFreehand'&&!state.options.area)||lines.includes(t)?2:3;if(t&&state.points.length>=min)finishDraw();else if(t){toast('Draw a little further to create the item.');renderDraft();}e.preventDefault();e.stopPropagation();};el.addEventListener('pointerup',finish,{capture:true});el.addEventListener('pointercancel',e=>{if(pointer===e.pointerId){pointer=null;state.freehandActive=false;updateLock();}},{capture:true});}
function addPanelRun(ps,opt){const clean=simplifyLine(ps,0.35),result=G.panels(clean,opt),id=uid(),guide=feature('route',{type:'LineString',coordinates:clean},{label:opt.name+' Trakway run',routeId:id,groupId:id,distance:result.distance,product:opt.product,generated:true,guideHidden:true,includeLegend:false});state.project.features.push(guide);state.project.features.push(feature('measure',{type:'LineString',coordinates:clean},{label:opt.name+' run length',distance:result.distance,routeId:id,groupId:id,generated:true,autoAnnotation:true,includeLegend:false}));const added=[];for(const p of result.panels){const f=feature('panel',p.geometry,{label:opt.name,product:opt.product,length:opt.length,width:opt.width,routeId:id,groupId:id,corner:p.corner,junctionRow:p.junctionRow||0,cornerRule:p.cornerRule||'',sabreUnverified:p.sabreUnverified||false,jointOffsetMm:p.jointOffsetMm||0,dimensionLocked:true,styleFill:opt.styleFill,styleColor:opt.styleColor,derived:true,includeLegend:true});state.project.features.push(f);added.push(f);}cancelDraw();state.selected=null;commit();toast(`${result.panels.length} panels added as one grouped Trakway run · Select mode.`);if(opt.product==='sabre'&&result.warnings.length)showModal('Review Sabre-X joints','<p>'+result.warnings.map(esc).join('</p><p>')+'</p>');}
function simplifyLine(ps,minM=.35){if(state.tool&&isFreehandTool(state.tool)&&state.options.smoothing===false)return copy(ps);const out=[];for(const p of ps){if(!out.length||G.distance(out.at(-1),p)>=minM)out.push(p);}if(out.length===1&&ps.length>1)out.push(ps.at(-1));return out;}
function pointInRingXY(p,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j],hit=((a[1]>p[1])!==(b[1]>p[1]))&&(p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1]+1e-12)+a[0]);if(hit)inside=!inside;}return inside;}
function addPanelFill(ps,opt){const clean=simplifyLine(ps,0.25);if(clean.length<3)throw Error('Sketch a larger panel area.');const origin=clean[0],pr=G.projection(origin),ring=clean.map(pr.xy),stepL=Math.max(.1,+opt.length-(+opt.overlap||0)),stepW=Math.max(.1,+opt.width-(+opt.lateralOverlap||0));let ang=0;if(ring.length>1){const dx=ring[1][0]-ring[0][0],dy=ring[1][1]-ring[0][1];ang=Math.atan2(dx,dy)*180/Math.PI;}const a=ang*Math.PI/180,u=[Math.sin(a),Math.cos(a)],v=[Math.cos(a),-Math.sin(a)],corners=ring.map(([x,y])=>[x*u[0]+y*u[1],x*v[0]+y*v[1]]),cx=corners.map(p=>p[0]),cy=corners.map(p=>p[1]),minX=Math.min(...cx)-stepL,maxX=Math.max(...cx)+stepL,minY=Math.min(...cy)-stepW,maxY=Math.max(...cy)+stepW,panels=[];for(let x=minX;x<=maxX;x+=stepL){for(let y=minY;y<=maxY;y+=stepW){const world=[u[0]*x+v[0]*y,u[1]*x+v[1]*y];if(!pointInRingXY(world,ring))continue;const c=pr.ll(world);panels.push(G.rectangle(c,+opt.length,+opt.width,ang));if(panels.length>5000)throw Error('This area would exceed 5,000 panels. Draw a smaller area.');}}const id=uid(),areaGeom={type:'Polygon',coordinates:[[...clean,clean[0].slice()]]};state.project.features.push(feature('area',areaGeom,{label:opt.name+' panelised area',routeId:id,groupId:id,generated:true,guideHidden:true,includeLegend:false}));const perimeter=[...clean,clean[0].slice()];state.project.features.push(feature('measure',{type:'LineString',coordinates:perimeter},{label:opt.name+' pad perimeter',distance:G.length(perimeter),routeId:id,groupId:id,generated:true,autoAnnotation:true,includeLegend:false}));const added=[];for(const g of panels){const f=feature('panel',g,{label:opt.name,product:opt.product,length:opt.length,width:opt.width,angle:ang,routeId:id,groupId:id,dimensionLocked:true,styleFill:opt.styleFill,styleColor:opt.styleColor,derived:true,includeLegend:true});state.project.features.push(f);added.push(f);}cancelDraw();state.selected=null;commit();toast(`${panels.length} panels filled as one group · Select mode.`);}
